import{_ as t,o as i,c as r,a2 as o}from"./chunks/framework.BDCokyix.js";const g=JSON.parse('{"title":"11. Risks and Technical Debt","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/11-risks-tech-debt.md","filePath":"architecture/arc42/11-risks-tech-debt.md","lastUpdated":1780254295000}'),a={name:"architecture/arc42/11-risks-tech-debt.md"};function s(n,e,l,c,d,u){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_11-risks-and-technical-debt" tabindex="-1">11. Risks and Technical Debt <a class="header-anchor" href="#_11-risks-and-technical-debt" aria-label="Permalink to &quot;11. Risks and Technical Debt&quot;">​</a></h1><p>This page tracks known architectural risks and “next refactor” items.</p><h2 id="security-risks-follow-ups" tabindex="-1">Security risks / follow-ups <a class="header-anchor" href="#security-risks-follow-ups" aria-label="Permalink to &quot;Security risks / follow-ups&quot;">​</a></h2><ul><li><strong>Canonical signing format</strong>: current signing uses CBOR but canonicalization is not guaranteed across implementations/versions; this is a prerequisite for robust cross-version signature verification.</li><li><strong>Signature verification completeness</strong>: ensure membership and issuer delegation chains are verified consistently on receipt (not just on issuance).</li><li><strong>Mode-gated HTTP auth</strong>: <code>somad bot</code> admin mode must remain authenticated/authorized; keep bot mode read-only.</li></ul><h2 id="networking-and-protocols" tabindex="-1">Networking and protocols <a class="header-anchor" href="#networking-and-protocols" aria-label="Permalink to &quot;Networking and protocols&quot;">​</a></h2><ul><li><strong>Large blob support</strong>: blob transfer is currently a single request/response message with size limits; implement chunking/streaming for larger assets.</li><li><strong>Multi-target join submission</strong>: requesters should try multiple candidate approvers to avoid hard dependency on a single online peer.</li><li><strong>Permission-gated blob downloads</strong>: tighten authorization for blob fetch based on membership/permissions.</li></ul><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><ul><li><strong>Repository consolidation</strong>: keep SQLx queries behind repositories; avoid leaking SQL into controllers.</li><li><strong>Schema evolution</strong>: maintain forward-compatible migrations and document how new tables are introduced.</li></ul><h2 id="product-ux" tabindex="-1">Product/UX <a class="header-anchor" href="#product-ux" aria-label="Permalink to &quot;Product/UX&quot;">​</a></h2><ul><li><strong>Discovery UX</strong>: improve “what peers can I join?” surfacing, especially in mixed LAN/WAN environments.</li><li><strong>Operational UX</strong>: provide better local commands or UI for inspecting peer connectivity and join status.</li></ul>',10)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
